// Reading Google Ads REST responses from an HTTP Request node that has
// "Full response" on (and usually "Never error"), with the body as text or JSON.

function gadsBody(r) {
  let body = r && (r.body !== undefined ? r.body : r.data);
  if (typeof body === 'string') {
    try {
      body = body ? JSON.parse(body) : null;
    } catch (e) {
      return { __unparsable: true };
    }
  }
  return body;
}

// Human-readable error from a failed call, or null when it succeeded.
function gadsError(r) {
  if (!r) return 'no response';
  if (r.error && r.statusCode === undefined) return String(r.error.message || JSON.stringify(r.error)).slice(0, 500);
  if (r.statusCode >= 200 && r.statusCode < 300) return null;
  const body = gadsBody(r);
  const first = Array.isArray(body) ? body[0] : body;
  const err = first && first.error;
  const detail = err && err.details && err.details[0] && err.details[0].errors && err.details[0].errors[0];
  const code = detail && detail.errorCode ? ` [${Object.values(detail.errorCode).join(',')}]` : '';
  return `${r.statusCode} ${(detail && detail.message) || (err && err.message) || 'error'}${code}`.slice(0, 500);
}

// searchStream / search -> { rows } or { error }.
function parseStream(r) {
  const error = gadsError(r);
  if (error) return { error };
  const body = gadsBody(r);
  if (body && body.__unparsable) return { error: 'response was not JSON' };
  const rows = [];
  for (const batch of Array.isArray(body) ? body : [body]) {
    for (const row of (batch && batch.results) || []) rows.push(row);
  }
  return { rows };
}
// ---- end shared/gads.js -----------------------------------------------------

// ---- ff-case-match/results.js (included by check.js and records.js) -------
// Reads an upload*Conversions response (full response, partialFailure on).
// Returns counts and error-code names only - never row data, because Google's
// messages can echo a click id.
function readUpload(resp, sent) {
  const out = { sent, accepted: 0, rejected: 0, reasons: {}, error: null };
  const requestError = gadsError(resp);
  if (requestError) {
    out.error = requestError.replace(/[A-Za-z0-9_-]{30,}/g, '[id]');
    out.rejected = sent;
    return out;
  }
  const body = gadsBody(resp) || {};
  const pf = body.partialFailureError;
  const bad = new Set();
  for (const d of (pf && pf.details) || []) {
    for (const e of d.errors || []) {
      const path = ((e.location && e.location.fieldPathElements) || []).find((f) => f.fieldName === 'conversions');
      const idx = path ? Number(path.index || 0) : -1;
      const code = e.errorCode ? Object.values(e.errorCode)[0] : 'UNKNOWN';
      if (idx >= 0) bad.add(idx);
      out.reasons[code] = (out.reasons[code] || 0) + 1;
    }
  }
  out.rejected = Math.min(sent, bad.size);
  out.accepted = sent - out.rejected;
  return out;
}
// ---- end ff-case-match/results.js -------------------------------------------

// Results of the validateOnly calls (one per upload kind), matched to their
// request with itemMatching(i), never by position. Decides whether the real
// upload runs: only for action "upload", and only if no request failed as a whole.
const plan = $('Plan uploads').first().json;
const results = {};
$input.all().forEach((item, i) => {
  const req = $('Upload requests').itemMatching(i).json;
  results[req.kind] = readUpload(item.json, req.sent);
});
const requestFailed = Object.values(results).some((r) => r.error);
const accepted = Object.values(results).reduce((s, r) => s + r.accepted, 0);
return [{ json: { results, go: plan.action === 'upload' && !requestFailed && accepted > 0 } }];

